(4336631, 624570, 83313, '<td valign="top">Very cute, or as cute a bug like this can get. How''s you get him to appear to be standing?</td>', 'Very cute, or as cute a bug like this can get. How''s you get him to appear to be standing?', '2007-12-26 16:53:49.000000', NULL, 1),
(4336638, 624923, 83313, '<td valign="top">Nice. This could be a portfolio shot for the musician. Other that the cut off elbow, (A very minor thing) there''s not much to complain about here.</td>', 'Nice. This could be a portfolio shot for the musician. Other that the cut off elbow, (A very minor thing) there''s not much to complain about here.', '2007-12-26 16:55:33.000000', NULL, 1),
