(4336646, 625122, 83313, '<td valign="top">Nicely done. Nice and straight. My eye flows right on up the building. I''m dizzy now...</td>', 'Nicely done. Nice and straight. My eye flows right on up the building. I''m dizzy now...', '2007-12-26 16:58:26.000000', NULL, 1),
(4336651, 624828, 83313, '<td valign="top">Great color and detail. Maybe a little too much fisheye for my own taste.</td>', 'Great color and detail. Maybe a little too much fisheye for my own taste.', '2007-12-26 16:59:31.000000', NULL, 1),
(4336658, 624735, 83313, '<td valign="top">The title almost works, though it seems slightly forced. This is not about titles, though. I like the subtle tones here. A little less centered may have been about the only thing I''d suggest.</td>', 'The title almost works, though it seems slightly forced. This is not about titles, though. I like the subtle tones here. A little less centered may have been about the only thing I''d suggest.', '2007-12-26 17:02:04.000000', NULL, 1),
(4336662, 624716, 83313, '<td valign="top">Nicely composed. I see a fair amount of compression artifacts in the sky and especially near the top edge of the left column. Not sure if you could have avoided that or not.</td>', 'Nicely composed. I see a fair amount of compression artifacts in the sky and especially near the top edge of the left column. Not sure if you could have avoided that or not.', '2007-12-26 17:04:10.000000', NULL, 1),
(4336669, 625030, 83313, '<td valign="top">I like this. Sepia often does not work for me when it is giving an old fashioned look to a modern scene, but you did not use it that way here. It enhances the clouds and the dreary day appearance.</td>', 'I like this. Sepia often does not work for me when it is giving an old fashioned look to a modern scene, but you did not use it that way here. It enhances the clouds and the dreary day appearance.', '2007-12-26 17:05:53.000000', NULL, 1),
(4336681, 624475, 79562, '<td valign="top">I really like this, but the red sidepaths (or whatever they are) are distracting to me - I wish the entire photo was B&amp;W</td>', 'I really like this, but the red sidepaths (or whatever they are) are distracting to me - I wish the entire photo was B&W', '2007-12-26 17:09:56.000000', NULL, 1),
