(4340267, 624973, 39850, '<td valign="top">Like the way you have brought out the colors in the train, creates ''segments''.  Your call of course, but I wonder whether the distant something far right and the greenery edging on the track cropped out, may have made this an even stronger image.  Like to have seen the perspective a bit stronger for this Challenge too, ''somehow''.</td>', 'Like the way you have brought out the colors in the train, creates ''segments''.  Your call of course, but I wonder whether the distant something far right and the greenery edging on the track cropped out, may have made this an even stronger image.  Like to have seen the perspective a bit stronger for this Challenge too, ''somehow''.', '2007-12-28 01:09:09.000000', NULL, 1),
(4340269, 625013, 42013, '<td valign="top">Another self portrait Joe? Very ghostly</td>', 'Another self portrait Joe? Very ghostly', '2007-12-28 01:10:06.000000', NULL, 1),
(4340288, 625076, 42013, '<td valign="top">ONe of my favorites. I think it''s the contrast and the emptyness, of the room and the buckets.</td>', 'ONe of my favorites. I think it''s the contrast and the emptyness, of the room and the buckets.', '2007-12-28 01:17:33.000000', NULL, 1),
(4340313, 624976, 65438, '<td valign="top">Too cute!</td>', 'Too cute!', '2007-12-28 01:31:42.000000', NULL, 1),
(4340330, 625113, 80167, '<td valign="top">I love it! The curved/slanted horizon line fits this photo perfectly. 9.</td>', 'I love it! The curved/slanted horizon line fits this photo perfectly. 9.', '2007-12-28 02:13:22.000000', NULL, 1),
(4340338, 624515, 32721, '<td valign="top">the detail and the tones are amazing</td>', 'the detail and the tones are amazing', '2007-12-28 02:32:28.000000', NULL, 1),
(4340554, 624565, 62989, '<td valign="top">Extraordinary - very beautiful</td>', 'Extraordinary - very beautiful', '2007-12-28 07:13:56.000000', NULL, 1),
