(4340610, 624473, 70514, '<td valign="top">Great line and love the processing.  I love the soft snow against train.</td>', 'Great line and love the processing.  I love the soft snow against train.', '2007-12-28 08:18:21.000000', NULL, 1),
(4340614, 624767, 70514, '<td valign="top">The gate gives the appearance of falling backwards.  Interesting and cool.</td>', 'The gate gives the appearance of falling backwards.  Interesting and cool.', '2007-12-28 08:19:26.000000', NULL, 1),
(4340616, 624698, 70514, '<td valign="top">Great dof, nice texture and repetition.</td>', 'Great dof, nice texture and repetition.', '2007-12-28 08:20:20.000000', NULL, 1),
