(4340840, 624866, 15711, '<td valign="top">OH WHAT A SWEETIE!!!!!!!Love the expression. Not sure if this really shows perspective but man, what a face. ;~D</td>', 'OH WHAT A SWEETIE!!!!!!!Love the expression. Not sure if this really shows perspective but man, what a face. ;~D', '2007-12-28 10:11:50.000000', NULL, 1),
(4340841, 625058, 84765, '<td valign="top">I don''t know what''s in the right side of the picture, but it could have been very interesting to see the shadows more clearly.</td>', 'I don''t know what''s in the right side of the picture, but it could have been very interesting to see the shadows more clearly.', '2007-12-28 10:12:04.000000', NULL, 1),
(4340842, 624250, 78196, '<td valign="top">The PP on this is to die for... Fabulously hectic shot.</td>', 'The PP on this is to die for... Fabulously hectic shot.', '2007-12-28 10:12:26.000000', NULL, 1),
(4340844, 624776, 78196, '<td valign="top">Super. Love the PP.</td>', 'Super. Love the PP.', '2007-12-28 10:12:43.000000', NULL, 1),
(4340845, 625095, 15711, '<td valign="top">I like the geometry.  I think I''d play with contrast a bit though. I like the composition.</td>', 'I like the geometry.  I think I''d play with contrast a bit though. I like the composition.', '2007-12-28 10:13:08.000000', NULL, 1),
(4340846, 624973, 55956, '<td valign="top">mmm I like this image, probably there is a bit of too much highlight and shadows or too much neat image and the photo have a too big "plastic" effect. 6</td>', 'mmm I like this image, probably there is a bit of too much highlight and shadows or too much neat image and the photo have a too big "plastic" effect. 6', '2007-12-28 10:13:24.000000', NULL, 1),
(4340847, 624976, 15711, '<td valign="top">AWWWWW Cute idea. Maybe a touch snapshot feeling but the sentiment is adorable.</td>', 'AWWWWW Cute idea. Maybe a touch snapshot feeling but the sentiment is adorable.', '2007-12-28 10:14:00.000000', NULL, 1),
(4340849, 624526, 84765, '<td valign="top">By turning the picture I think you should have made the bridge completely parallel to the to of the frame.</td>', 'By turning the picture I think you should have made the bridge completely parallel to the to of the frame.', '2007-12-28 10:14:14.000000', NULL, 1),
(4340850, 624973, 78196, '<td valign="top">Nice and sharp but a little over-processed for my taste - I could do without the glow around the front of the train. Although we get a good sense of perspective the composition in itself could be somewhat more imaginative I think.</td>', 'Nice and sharp but a little over-processed for my taste - I could do without the glow around the front of the train. Although we get a good sense of perspective the composition in itself could be somewhat more imaginative I think.', '2007-12-28 10:14:36.000000', NULL, 1),
(4340852, 623681, 78196, '<td valign="top">Striking shot.</td>', 'Striking shot.', '2007-12-28 10:15:41.000000', NULL, 1),
(4340853, 624847, 15711, '<td valign="top">Man, nothing gets me more than a guy playing a guitar. ;~D</td>', 'Man, nothing gets me more than a guy playing a guitar. ;~D', '2007-12-28 10:15:42.000000', NULL, 1),
(4340855, 624316, 78196, '<td valign="top">Great stuff. Love the symmetry and the PP is spot-on.</td>', 'Great stuff. Love the symmetry and the PP is spot-on.', '2007-12-28 10:16:56.000000', NULL, 1),
(4340857, 624316, 55956, '<td valign="top">.. and the Institut de France ....   7</td>', '.. and the Institut de France ....   7', '2007-12-28 10:17:57.000000', NULL, 1),
(4340858, 625007, 78196, '<td valign="top">There''s such energy and mystery in this shot and the PP is sublime. Captivating.</td>', 'There''s such energy and mystery in this shot and the PP is sublime. Captivating.', '2007-12-28 10:18:23.000000', NULL, 1),
(4340860, 625015, 78196, '<td valign="top">I could look at this all day. Dark, brooding, mysterious yet delicate. Quite incomprehensible but a completely wonderful image.</td>', 'I could look at this all day. Dark, brooding, mysterious yet delicate. Quite incomprehensible but a completely wonderful image.', '2007-12-28 10:19:21.000000', NULL, 1),
(4340861, 624991, 55956, '<td valign="top">these photos are always difficult because the sky is always over exposed, perhaps an hdr could be useful here. 6</td>', 'these photos are always difficult because the sky is always over exposed, perhaps an hdr could be useful here. 6', '2007-12-28 10:20:01.000000', NULL, 1),
(4340862, 625076, 84765, '<td valign="top">I can almost smell the room!</td>', 'I can almost smell the room!', '2007-12-28 10:20:05.000000', NULL, 1),
(4340863, 624970, 84765, '<td valign="top">I love it. Interesting combination of moving clouds and steady starts and landscape.</td>', 'I love it. Interesting combination of moving clouds and steady starts and landscape.', '2007-12-28 10:21:44.000000', NULL, 1),
(4340868, 624620, 84765, '<td valign="top">I think it is a shame that the picture has dark corners in the left side.</td>', 'I think it is a shame that the picture has dark corners in the left side.', '2007-12-28 10:23:58.000000', NULL, 1),
