INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4340880, 624034, 84765, '<td valign="top">Why don''t we see his face?<br/> <br/>Good contrast, sharpness and color.</td>', 'Why don''t we see his face? Good contrast, sharpness and color.', '2007-12-28 10:27:54.000000', NULL, 1),
(4340881, 625123, 84765, '<td valign="top">Interesting how the corny look adds something to the environment.</td>', 'Interesting how the corny look adds something to the environment.', '2007-12-28 10:28:51.000000', NULL, 1),
(4340989, 624219, 15305, '<td valign="top">Actually, I prefer the perspective you used on your "Textures V" entry, I gave that one a 9. This gets a 7 from me.  What an interesting and uncommon subject!!  I''d never seen a goat so colorful and with such long ears!!</td>', 'Actually, I prefer the perspective you used on your "Textures V" entry, I gave that one a 9. This gets a 7 from me.  What an interesting and uncommon subject!!  I''d never seen a goat so colorful and with such long ears!!', '2007-12-28 11:51:06.000000', NULL, 1),
(4341003, 624823, 3102, '<td valign="top">Kerry Park!</td>', 'Kerry Park!', '2007-12-28 12:02:08.000000', NULL, 1),
(4341011, 624316, 59335, '<td valign="top">This is absolutely beautiful. AFter the challenge is over...I would suggest adding some more sky above the building so you can get the rest of that weather vane in.</td>', 'This is absolutely beautiful. AFter the challenge is over...I would suggest adding some more sky above the building so you can get the rest of that weather vane in.', '2007-12-28 12:07:05.000000', NULL, 1),
(4341080, 624479, 38248, '<td valign="top">I predict a top ten for this one.  Nice work.</td>', 'I predict a top ten for this one.  Nice work.', '2007-12-28 12:59:54.000000', NULL, 1),
(4341089, 624247, 3087, '<td valign="top">I like the sheer variety of parallel lines here - the lampposts, of course, are the strongest, the railings, the shadows of the railing along the ground and even the distant pilings in the water. The composition is very pleasing and the high contrast black and white works very well. I like the long shadows from the time of day too as well as your focal point woman on a phone.</td>', 'I like the sheer variety of parallel lines here - the lampposts, of course, are the strongest, the railings, the shadows of the railing along the ground and even the distant pilings in the water. The composition is very pleasing and the high contrast black and white works very well. I like the long shadows from the time of day too as well as your focal point woman on a phone.', '2007-12-28 13:06:28.000000', NULL, 1),
(4341094, 625080, 3087, '<td valign="top">I like the subject but my first thought is that it''s not sharp enough in the area of focus and my second is that the snow-covered line as it comes towards the viewer and blurs out is actually quite distracting and too overpowering a part of the whole. I do love the needles of frost on the peg though and would be interested in a similar shot bring the main peg nearer to the viewer and including more of the line of pegs in the background for perspective.</td>', 'I like the subject but my first thought is that it''s not sharp enough in the area of focus and my second is that the snow-covered line as it comes towards the viewer and blurs out is actually quite distracting and too overpowering a part of the whole. I do love the needles of frost on the peg though and would be interested in a similar shot bring the main peg nearer to the viewer and including more of the line of pegs in the background for perspective.', '2007-12-28 13:08:16.000000', NULL, 1),
(4341096, 624169, 3087, '<td valign="top">Wow, great image - SO much to look at. I really like the way there are different levels or areas to look at - the distant people on the higher level, the roof with it''s futuristic circles and diagonals and the platform level with colourful yellow lines and people. Leading lines take me first to the lady in yellow and red but I quickly move all around the frame. Brilliant!</td>', 'Wow, great image - SO much to look at. I really like the way there are different levels or areas to look at - the distant people on the higher level, the roof with it''s futuristic circles and diagonals and the platform level with colourful yellow lines and people. Leading lines take me first to the lady in yellow and red but I quickly move all around the frame. Brilliant!', '2007-12-28 13:09:56.000000', NULL, 1),
(4341097, 624823, 3087, '<td valign="top">Unusual image with lots of colour, energy and fun together with clever framing.  Works.</td>', 'Unusual image with lots of colour, energy and fun together with clever framing.  Works.', '2007-12-28 13:11:34.000000', NULL, 1),
(4341098, 625121, 3087, '<td valign="top">Great sense of the turn in that motion blur, very nicely done.</td>', 'Great sense of the turn in that motion blur, very nicely done.', '2007-12-28 13:11:53.000000', NULL, 1),
(4341100, 625113, 3087, '<td valign="top">Lovely sweep of landscape along the bottom - I really like how little of the overall frame it takes up and yet is still so striking. Love the way the haze mutes the trees from black silhouettes to mid-grey to almost invisible. And that sky, oh my, how fabulous, with the wonderful lines and textures of the clouds. A favourite.</td>', 'Lovely sweep of landscape along the bottom - I really like how little of the overall frame it takes up and yet is still so striking. Love the way the haze mutes the trees from black silhouettes to mid-grey to almost invisible. And that sky, oh my, how fabulous, with the wonderful lines and textures of the clouds. A favourite.', '2007-12-28 13:13:08.000000', NULL, 1),
(4341101, 624301, 3087, '<td valign="top">Great sense of scale between the architecture (which is impressive indeed) and the people. Works well.</td>', 'Great sense of scale between the architecture (which is impressive indeed) and the people. Works well.', '2007-12-28 13:13:41.000000', NULL, 1),
(4341102, 625015, 3087, '<td valign="top">Surreal, odd, intriguing but definitely interesting!</td>', 'Surreal, odd, intriguing but definitely interesting!', '2007-12-28 13:14:25.000000', NULL, 1),
(4341104, 624475, 3087, '<td valign="top">The road lines really do lead the viewer in. I like the frost and muted tones very much but find the red verges quite distracting. I wonder if you could desaturate the red channel to fade them to grey and make them less of a focal point?</td>', 'The road lines really do lead the viewer in. I like the frost and muted tones very much but find the red verges quite distracting. I wonder if you could desaturate the red channel to fade them to grey and make them less of a focal point?', '2007-12-28 13:16:45.000000', NULL, 1),
(4341105, 625123, 3087, '<td valign="top">Love the grain as well as the ascent from darkness to light. Simple, uncluttered setting allows focus to be on the child as well as the shapes/light/shadow.</td>', 'Love the grain as well as the ascent from darkness to light. Simple, uncluttered setting allows focus to be on the child as well as the shapes/light/shadow.', '2007-12-28 13:18:06.000000', NULL, 1),
(4341393, 624301, 83067, '<td valign="top">Great dimensional photograph.</td>', 'Great dimensional photograph.', '2007-12-28 16:02:02.000000', NULL, 1),
(4341399, 625082, 83067, '<td valign="top">cannot argue with the title. :-) nice image</td>', 'cannot argue with the title. :-) nice image', '2007-12-28 16:03:34.000000', NULL, 1),
(4341655, 624585, 3087, '<td valign="top">Makes a heck of a lot more sense (to me) in Hidden City than it does in Perspective!!!</td>', 'Makes a heck of a lot more sense (to me) in Hidden City than it does in Perspective!!!', '2007-12-28 17:35:15.000000', NULL, 1),
(4341695, 624709, 72530, '<td valign="top">Most interesting shot of the Washington Monument I''ve ever seen.</td>', 'Most interesting shot of the Washington Monument I''ve ever seen.', '2007-12-28 18:02:41.000000', NULL, 1),
(4341705, 624475, 72530, '<td valign="top">Magnificent!</td>', 'Magnificent!', '2007-12-28 18:10:35.000000', NULL, 1),
(4341722, 624828, 86958, '<td valign="top">Very nice perspective. I like the blue sky background.</td>', 'Very nice perspective. I like the blue sky background.', '2007-12-28 18:20:38.000000', NULL, 1),
(4341723, 624169, 86958, '<td valign="top">Very nice perspective of lines with curves.</td>', 'Very nice perspective of lines with curves.', '2007-12-28 18:20:51.000000', NULL, 1),
(4341725, 624993, 86958, '<td valign="top">Very nice and different.</td>', 'Very nice and different.', '2007-12-28 18:20:56.000000', NULL, 1),
