(4341729, 625117, 86958, '<td valign="top">Nice shot. Very nice.</td>', 'Nice shot. Very nice.', '2007-12-28 18:21:32.000000', NULL, 1),
(4341971, 625113, 88291, '<td valign="top">Is that a helicopter back there?  Seems out of place in this type of picture.</td>', 'Is that a helicopter back there?  Seems out of place in this type of picture.', '2007-12-28 20:26:45.000000', NULL, 1),
(4341974, 624620, 88291, '<td valign="top">Good lighting effect.</td>', 'Good lighting effect.', '2007-12-28 20:27:59.000000', NULL, 1),
(4341976, 624620, 53243, '<td valign="top">This looks like fun!</td>', 'This looks like fun!', '2007-12-28 20:29:01.000000', NULL, 1),
(4341980, 624866, 88291, '<td valign="top">Any dog-lover would appreciate this one. Good, intense up-front focus.</td>', 'Any dog-lover would appreciate this one. Good, intense up-front focus.', '2007-12-28 20:30:23.000000', NULL, 1),
(4341983, 625120, 53243, '<td valign="top">very nice capture and perspective</td>', 'very nice capture and perspective', '2007-12-28 20:30:59.000000', NULL, 1),
