(4346697, 625104, 68035, '<td valign="top">Jeez...where the heck was everyones Christmas spirit...I thought this was a wonderful shot for the challenge and hit the idea of perspective perfectly (it transported me back to a time when I was 5 years old and I was being told that I had to be good if I wanted presents)<br/> <br/>As for the comments about overdoing the NN...Well I think this may be true for a ''normal'' portrait but I thought given the subject it added to the slight magical other worldly feel about father christmas</td>', 'Jeez...where the heck was everyones Christmas spirit...I thought this was a wonderful shot for the challenge and hit the idea of perspective perfectly (it transported me back to a time when I was 5 years old and I was being told that I had to be good if I wanted presents) As for the comments about overdoing the NN...Well I think this may be true for a ''normal'' portrait but I thought given the subject it added to the slight magical other worldly feel about father christmas', '2007-12-31 03:27:08.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4346704, 624833, 70689, '<td valign="top">well deserved blue, great shot!</td>', 'well deserved blue, great shot!', '2007-12-31 03:37:22.000000', NULL, 0),
(4346707, 624119, 68035, '<td valign="top">Well, you did not need to worry about the crookedness of the shot as one of the beautiful things about these old tressle bridges is the way they are not geometrically perfect.<br/> <br/>Another beautiful image that met the challenge to a T.  I love the fact that the mans long grey hair seems to compliment the age of the bridge and the darkness of what lies beyond the bridge gives a feeling of mstery (and a touch of foreboding) about where the path he is taking may lead him<br/> <br/>Beautiful image and another great story that only enhances it</td>', 'Well, you did not need to worry about the crookedness of the shot as one of the beautiful things about these old tressle bridges is the way they are not geometrically perfect. Another beautiful image that met the challenge to a T.  I love the fact that the mans long grey hair seems to compliment the age of the bridge and the darkness of what lies beyond the bridge gives a feeling of mstery (and a touch of foreboding) about where the path he is taking may lead him Beautiful image and another great story that only enhances it', '2007-12-31 03:39:21.000000', NULL, 0),
(4346708, 624587, 5885, '<td valign="top">Dude, you did well. Coolazz photo. Well deserved PB! Who knows, you might be top 20 in a day or two ;-)</td>', 'Dude, you did well. Coolazz photo. Well deserved PB! Who knows, you might be top 20 in a day or two ;-)', '2007-12-31 03:40:16.000000', NULL, 0),
(4346716, 624587, 68035, '<td valign="top">Jason<br/> <br/>Your shots are just getting better and better.  I love the centred composition and the sharpness of the individual panels.  As for the sky well it is just supreme...great and stunning colours<br/> <br/>Many congratulations on the new PB and on your second 6+ score<br/> <br/>Superb shot</td>', 'Jason Your shots are just getting better and better.  I love the centred composition and the sharpness of the individual panels.  As for the sky well it is just supreme...great and stunning colours Many congratulations on the new PB and on your second 6+ score Superb shot', '2007-12-31 03:42:24.000000', NULL, 0),
(4346717, 624885, 41337, '<td valign="top">I love that b/w conversion. I need to play with calculations. Got any tips?</td>', 'I love that b/w conversion. I need to play with calculations. Got any tips?', '2007-12-31 03:42:35.000000', NULL, 0),
(4346721, 625007, 41337, '<td valign="top">Beautiful. It always amazes me how a photo can get so many favs during the challenge yet barely makes the top ten.</td>', 'Beautiful. It always amazes me how a photo can get so many favs during the challenge yet barely makes the top ten.', '2007-12-31 03:46:49.000000', NULL, 0),
(4346722, 624894, 68035, '<td valign="top">Barbara<br/> <br/>Great image, which was set off perfectly by the wonderous blueness of the sky and the vapour trail leading across it<br/> <br/>Super sharpness on the building itself.  I love the fact that I can imagine myself looking up at this building and seeing what you have captured<br/> <br/>Great for the challenge and underrated in my opinion</td>', 'Barbara Great image, which was set off perfectly by the wonderous blueness of the sky and the vapour trail leading across it Super sharpness on the building itself.  I love the fact that I can imagine myself looking up at this building and seeing what you have captured Great for the challenge and underrated in my opinion', '2007-12-31 03:46:54.000000', NULL, 0),
